// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;
    bytes4 constant ERC165_ID = 0x01ffc9a7;
    bytes4 constant ACCESS_CONTROL_ID = 0x7965db0b;

    function setUp() public { c = new Size(); }

    function testFuzz_property(bytes4 interfaceId) public {
        // 1. no restriction needed: every bytes4 value is an admissible interfaceId probe
        // 2. drive c through its public supportsInterface view
        bool result = c.supportsInterface(interfaceId);
        // 3. general rule: the answer must be true exactly for the two supported interface ids
        assertTrue(result == (interfaceId == ERC165_ID || interfaceId == ACCESS_CONTROL_ID));
    }
}
